function missing(){return `<div class="empty panel">${mascot('sleepy',96)}<h1>ไม่พบหน้าที่เลือก</h1><p>เลือกบทเรียนจากรายการอีกครั้งได้เลย</p>${link('courses','ไปที่บทเรียน')}</div>`;}
function badgeHTML(b){const pct=Math.round(b.have/b.need*100);return `<article class="badge-card ${b.earned?'earned':'locked'}"><span class="bc-icon" aria-hidden="true">${b.icon}</span><b>${e(b.title)}</b><small>${e(b.detail)}</small>${b.earned?'<span class="bc-state">ได้แล้ว ✓</span>':`${meter(pct,`ความคืบหน้าเหรียญ ${b.title}`)}<span class="bc-state">${progressText(b)}</span>`}</article>`;}
function awards(){
 const xp=xpTotal(state),lv=levelInfo(xp),parts=xpParts(state),list=badges(state),got=list.filter(b=>b.earned).length,best=bestStreak(state),n=v=>v.toLocaleString('th-TH');
 return `${heading('รางวัลของฉัน','เรียนทุกวันเพื่อเก็บ XP เลเวลอัป และปลดล็อกเหรียญ · คำนวณจากความคืบหน้าที่บันทึกไว้')}
 <section class="level-hero">${mascot(lv.next===null?'cheer':'happy',120)}<div class="lh-body"><span class="lv-chip"><span aria-hidden="true">${lv.icon}</span> เลเวล ${lv.level}</span><h2>${e(lv.title)}</h2>${meter(lv.percent,'ความคืบหน้าสู่เลเวลถัดไป')}<p><b>${n(xp)} XP</b>${lv.next===null?' · เลเวลสูงสุดแล้ว 👑':` · อีก ${n(lv.toNext)} XP ถึงเลเวล ${lv.level+1}`}</p></div><div class="lh-stats"><div><b>${got}/${list.length}</b><span>เหรียญ</span></div><div><b>${best}</b><span>วันติดสูงสุด</span></div></div></section>
 <div class="section-heading"><div><h2>🏅 เหรียญรางวัล</h2><p>ได้แล้ว ${got} จาก ${list.length} เหรียญ · เหรียญที่ยังล็อกบอกว่าเหลืออีกเท่าไร</p></div></div>
 <div class="badge-grid">${list.map(badgeHTML).join('')}</div>
 <div class="split-grid"><section class="panel"><h2>วิธีเก็บ XP</h2><ul class="xp-list">${XP_SOURCES.map(([key,ic,label,rule])=>`<li><span class="xp-ic" aria-hidden="true">${ic}</span><div><b>${label}</b><small>${rule}</small></div><strong>${n(parts[key])} XP</strong></li>`).join('')}</ul></section><section class="panel"><h2>เส้นทางเลเวล</h2><ol class="level-ladder">${LEVELS.map(([min,title,ic],i)=>`<li class="${i+1<lv.level?'past':i+1===lv.level?'current':''}"><span aria-hidden="true">${ic}</span><b>เลเวล ${i+1} · ${e(title)}</b><small>${n(min)} XP</small></li>`).join('')}</ol></section></div>
 <p class="quiet-note">XP และเหรียญเป็นแรงจูงใจในแอปเท่านั้น ไม่ใช่คะแนนหรือผลการเรียนของมหาวิทยาลัย · ยกเลิกเครื่องหมายอ่านจบ XP ของบทนั้นจะหายไปด้วย ส่วน XP จากโจทย์ที่ตอบถูกแล้วยังอยู่</p>`;
}
function updateNav(){
 const active=(currentView==='lesson'||currentView==='course')?'courses':currentView==='prep'?'exams':currentView==='note'?'notes':currentView,place=placeOf(currentView);
 const xp=xpTotal(state),lv=levelInfo(xp),s=streak(state,today());
 const navLink=([key,i,label])=>`<a class="nav-link ${active===key?'active':''}" href="#${key}" ${active===key?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${key==='courses'?`<small>${lessons.length}</small>`:''}</a>`;
 document.querySelector('#navigation').innerHTML=navGroups.map(([title,items])=>`<div class="nav-group${title.startsWith('อื่น')?' nav-other':''}">${title?`<span class="nav-group-title">${title}</span>`:''}${items.map(navLink).join('')}</div>`).join('');
 document.querySelector('#bottom-nav').innerHTML=places.map(([key,i,label])=>`<a class="${place===key?'active':''}" href="#${key}" ${place===key?'aria-current="page"':''}>${icon(i,22)}<span>${label}</span></a>`).join('');
 document.querySelector('#top-stats').innerHTML=`<a class="top-chip" href="#awards" aria-label="เรียนต่อเนื่อง ${s} วัน · เลเวล ${lv.level} ${e(lv.title)} ${xp} XP"><span aria-hidden="true">🔥</span><b>${s}</b><i aria-hidden="true"></i><span aria-hidden="true">${lv.icon}</span><b>Lv.${lv.level}</b></a>`;
 document.querySelector('#side-level').innerHTML=`<span class="sl-icon" aria-hidden="true">${lv.icon}</span><span class="sl-body"><b>Lv.${lv.level} ${e(lv.title)}</b>${meter(lv.percent,'ความคืบหน้าสู่เลเวลถัดไป')}<small>${xp.toLocaleString('th-TH')} XP${lv.next===null?' · สูงสุดแล้ว':` · อีก ${lv.toNext.toLocaleString('th-TH')} XP`}</small></span>`;
 document.querySelector('#breadcrumb').textContent=currentView==='lesson'?`${currentId.split('-')[0]} / ติวก่อนเรียน`:currentView==='prep'?`${currentId} / แนวข้อสอบ`:(navItems.find(n=>n[0]===currentView)?.[2]||{course:'ติวก่อนเรียนรายวิชา',about:'แหล่งเรียนรู้',settings:'ตั้งค่า',menu:'เมนูทั้งหมด'}[currentView]||'ห้องเรียน');
}
// Thin bar at the top of a lesson that fills as the learner scrolls through it.
function readProgress(){const root=document.documentElement,bar=document.getElementById('read-progress');if(!bar?.style||!root.scrollHeight)return;const max=root.scrollHeight-(globalThis.innerHeight||0);bar.style.setProperty('--read',currentView==='lesson'&&max>0?Math.min(1,Math.max(0,(globalThis.scrollY||0)/max)).toFixed(3):'0');}
function render(keepScroll=false){
 destroyEditor();const oldY=window.scrollY;document.documentElement.dataset.font=state.font;document.documentElement.dataset.view=currentView;updateNav();
 const info=studySpace.info();
 main.innerHTML=({home,debt:()=>{adoptLocalDebt();return debtPage(debtStore);},practice:()=>studySections('practice')+practicePage(state,currentId),documents:()=>documentsPage(currentId),courses:courseLibrary,classroom:classroomPage,course:()=>coursePage(currentId),prep:()=>prepPage(currentId),lesson:()=>lessonPage(currentId),review,plan,registration,calendar:()=>planningNav('calendar')+calendarPage(),menu:menuPage,exams:examPage,notes,note:()=>notePage(studySpace,currentId),account:()=>accountPage(studySpace),resources:()=>resourcesPage(state),about,settings,awards}[currentView]||missing)();
 fresh=null;
 if(typeof document.querySelectorAll==='function')document.querySelectorAll('[data-sync-status]').forEach(el=>el.textContent=info.status);
 document.title=`${currentView==='lesson'?(lessonById(currentId)?.title||'บทเรียน'):document.querySelector('#breadcrumb').textContent} · RU Study Planner`;
 if(info.canEdit&&currentView==='note'&&typeof window.location!=='undefined')mountEditor(studySpace,currentId);
 if(keepScroll)window.scrollTo(0,oldY);else window.scrollTo(0,0);
 readProgress();
}
function navigate(){const raw=location.hash.startsWith('#space=')?'home':location.hash.slice(1)||'home';const [view,id]=raw.split('/');if(view!=='review')sessionReviewed=0;currentView=view;currentId=id||'';reviewQueue=null;resetPracticeSession();if(currentView==='lesson'&&lessonById(currentId)&&studySpace.info().canEdit){state.lastLesson=currentId;save();}render();main.classList.remove('page-enter');void main.offsetWidth;main.classList.add('page-enter');main.focus({preventScroll:true});}
function download(name,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportAll(){download(`ru-study-backup-${today()}.json`,JSON.stringify(state,null,2),'application/json');toast('ส่งออกไฟล์สำรองแล้ว');}
function exportPlan(){const rows=[['ภาค','รหัส','รายวิชา','หน่วยกิต','หมวด','ภาระประมาณ','วันสอบ','คาบ','ผลสอบที่บันทึกเอง','เหตุผลลำดับเรียน'],...planSummary(state).termRows.flatMap(t=>t.courses.map(c=>[t.name,c.id,c.title,3,categories[c.category],c.load,c.exam?thaiDate(c.exam):'รอประกาศ',c.slot||'',state.grades[c.id]||'',c.reason]))];const csv='﻿'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');download('ru-study-plan-all-terms.csv',csv,'text/csv;charset=utf-8');}
function toggleBlock(id,rect){const day=planDate,list=state.planDone[day]||[];state.planDone[day]=list.includes(id)?list.filter(v=>v!==id):[...list,id];const keep=Object.keys(state.planDone).sort().slice(-400);for(const k of Object.keys(state.planDone))if(!keep.includes(k))delete state.planDone[k];fresh='block:'+id;save();render(true);const plan=dailyPlan(state,day),all=plan.done===plan.blocks.length;if(!list.includes(id)){toast(all?'ครบแผนวันนี้แล้ว เก่งมาก! 🎉':'ทำเสร็จอีกหนึ่งช่วง ✓');if(all)confetti(rect);}}
// XP floats up on every gain; a new level also gets the level-up card.
function reward(before,rect){const after=xpTotal(state);if(after<=before)return;floatXP(rect,after-before);const was=levelInfo(before),now=levelInfo(after);if(now.level>was.level){levelUp(now);toast(`เลเวลอัป! เลเวล ${now.level} · ${now.title} ${now.icon}`);}}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
 if(action==='fx-close'){closeLevelUp();return;}
 if(action==='term'){b.setAttribute?.('aria-pressed',String(b.getAttribute?.('aria-pressed')!=='true'));return;}
 if(action==='terms-all'){const list=typeof document.querySelectorAll==='function'?[...document.querySelectorAll('#section-terms .term')]:[],open=list.some(t=>t.getAttribute('aria-pressed')!=='true');list.forEach(t=>t.setAttribute('aria-pressed',String(open)));b.textContent=open?'ปิดคำอธิบายทั้งหมด':'เปิดดูทั้งหมด';return;}
 if(action==='debt-remove'){if(currentView!=='debt'||!confirm('ลบรายการจ่ายนี้? ยอดสะสมและเงินต้นคงเหลือจะคำนวณใหม่'))return;const error=debtAction(action,b.dataset,debtStore);const keepOpen=document.querySelector('#debt-history')?.open;render(true);if(keepOpen)document.querySelector('#debt-history')?.setAttribute?.('open','');toast(error||'ลบรายการจ่ายแล้ว');return;}
 if(action.startsWith('account-')){accountAction(action,studySpace,render,toast);return;}
 if(action.startsWith('nb-')&&!studySpace.info().canEdit){toast(studySpace.info().status);return;}
 if(action.startsWith('nb-')){notebookAction(action,b.dataset,studySpace,state,render,toast);return;}
 if(action.startsWith('cal-')){if(action==='cal-export'){download('ru-study-calendar-2-2569.ics',calendarDownload(),'text/calendar;charset=utf-8');toast('ดาวน์โหลดปฏิทินทั้งเทอมตามตัวกรองแล้ว');}else if(calendarAction(action,b.dataset))render(true);return;}
 if(action==='registration-term'||action==='registration-find'){const id=Number(b.dataset.term);if(terms.some(t=>t.id===id)){registrationTerm=id;regFocus=action==='registration-find'?b.dataset.course:'';render(true);document.querySelector('.registration-term.active')?.scrollIntoView?.({block:'nearest',inline:'nearest'});if(regFocus)document.querySelector('#reg-row-'+regFocus)?.scrollIntoView?.({block:'center',behavior:'smooth'});}return;}
 if(action==='refresh-content'){location.reload();return;}
 if(!studySpace.info().canEdit&&!['plan-today','section','mode','flip','next','prev','review-course'].includes(action)){toast('กำลังเชื่อมต่อพื้นที่บันทึก คุณอ่านบทเรียนและดูตารางได้ระหว่างรอ');return;}
 const rect=typeof b.getBoundingClientRect==='function'?b.getBoundingClientRect():null,before=xpTotal(state);
 if(action==='plan-today'){planDate=today()<STUDY_START?STUDY_START:today();planToolsOpen=true;render(true);return;}
 if(action.startsWith('practice-')){if(practiceAction(action,b.dataset,state))save();render(true);reward(before,rect);return;}
 if(action==='font'){state.font=state.font==='large'?'normal':'large';save();render(true);}
 if(action==='section')document.getElementById(`section-${b.dataset.index}`)?.scrollIntoView({behavior:'smooth',block:'start'});
 if(action==='block')toggleBlock(b.dataset.id,rect);
 if(action==='hours'){const v=Number(b.dataset.value);if(!studyHours.includes(v))return;state.hourOverrides[planDate]=v;planToolsOpen=true;save();render(true);toast(`ปรับแผนวันที่เลือกเป็น ${v} ชั่วโมงแล้ว`);}
 if(action==='prep-answer'){const code=b.dataset.course,g=prep[code],i=Number(b.dataset.index),v=Number(b.dataset.value);if(!g||!g.questions[i]||!Number.isInteger(v)||v<0||v>=g.questions[i].options.length)return;const p=state.prep[code]||(state.prep[code]={answers:{},submitted:false,best:null,last:null});if(prepMode==='exam'?p.submitted:Number.isInteger(p.answers[i]))return;p.answers[i]=v;if(prepMode==='practice')recordPractice(state,`prep:${code}:${i}`,v,today());let finished=null;if(prepMode==='practice'&&Object.keys(p.answers).length===g.questions.length){const r=prepResult(state,code);p.last=r.correct;p.best=Math.max(p.best??0,r.correct);finished=r;}fresh=`prep:${code}:${i}`;save();render(true);if(finished){toast(`ครบทุกข้อแล้ว ได้ ${finished.correct}/${finished.total} คะแนน`);if(finished.correct>=finished.total*.8)confetti(rect);}}
 if(action==='prep-submit'){const code=b.dataset.course,p=state.prep[code];if(!prep[code]||!p||p.submitted)return;p.submitted=true;for(const [i,v]of Object.entries(p.answers))recordPractice(state,`prep:${code}:${i}`,v,today());const r=prepResult(state,code);p.last=r.correct;p.best=Math.max(p.best??0,r.correct);fresh='submit:'+code;save();render(true);toast(`ได้ ${r.correct}/${r.total} คะแนน เลื่อนดูเฉลยแต่ละข้อได้เลย`);if(r.correct>=r.total*.8)confetti(rect);}
 if(action==='prep-reset'){const code=b.dataset.course;if(!prep[code])return;const p=state.prep[code];if(p&&Object.keys(p.answers).length&&!confirm('ล้างคำตอบชุดนี้แล้วเริ่มทำใหม่? คะแนนดีสุดยังเก็บไว้'))return;state.prep[code]={answers:{},submitted:false,best:p?.best??null,last:p?.last??null};save();render(true);document.getElementById('mock-title')?.scrollIntoView({block:'start'});}
 if(action==='prep-mode'){const code=b.dataset.course,mode=b.dataset.mode;if(!['practice','exam'].includes(mode)||mode===prepMode)return;const p=state.prep[code];if(p&&Object.keys(p.answers).length){if(!confirm('เปลี่ยนโหมดจะล้างคำตอบที่ทำค้างไว้ (คะแนนดีสุดยังเก็บไว้) ต้องการเปลี่ยนไหม?'))return;state.prep[code]={...p,answers:{},submitted:false};save();}prepMode=mode;render(true);}
 if(action==='answer'){const l=lessonById(b.dataset.lesson),i=Number(b.dataset.index),v=Number(b.dataset.value);if(!l||!l.questions[i]||v<0||v>=l.questions[i].options.length)return;state.answers[`${l.id}:${i}`]=v;fresh=`answer:${l.id}:${i}`;recordPractice(state,`lesson:${l.id}:${i}`,v,today());save();if(reviewMode==='quiz'&&mistakesOnly&&currentView==='review'){toast(v===l.questions[i].answer?'ตอบถูกแล้ว นำออกจากข้อที่ต้องทบทวน':'บันทึกแล้ว ดูคำอธิบายเพื่อทบทวน');}render(true);}
 if(action==='retry'){for(const key of Object.keys(state.answers))if(key.startsWith(b.dataset.id+':'))delete state.answers[key];save();render(true);}
 if(action==='retry-one'){delete state.answers[b.dataset.id];save();render(true);}
 if(action==='complete'){const id=b.dataset.id;if(!lessonById(id))return;if(state.completed.includes(id)){state.completed=state.completed.filter(v=>v!==id);state.sessions=state.sessions.filter(v=>!(v.lesson===id&&v.date===today()));}else {state.completed.push(id);if(!state.sessions.some(v=>v.lesson===id&&v.date===today()))state.sessions.push({lesson:id,date:today()});}const now=state.completed.includes(id);if(now)fresh='complete:'+id;save();render(true);toast(now?'อ่านจบแล้ว เก่งมาก! 🎉 การ์ดของบทนี้เข้าคิวทบทวนแล้ว':'ยกเลิกเครื่องหมายแล้ว');if(now)confetti(rect);}
 if(action==='mode'){reviewMode=b.dataset.mode;quizIndex=0;flipped=false;reviewQueue=null;render(true);}
 if(action==='flip'){flipped=!flipped;render(true);}
 if(action==='remember'){reviewCard(state,b.dataset.id,b.dataset.value==='yes');sessionReviewed++;save();flipped=false;render(true);if(!cardsForReview(state,reviewCourse,today(),includeUnread).length){toast('ทบทวนครบสำหรับวันนี้แล้ว เก่งมาก! 🎉');confetti(rect);}}
 if(action==='quiz-next'){quizIndex++;render(true);}
 if(action==='quiz-prev'){quizIndex=Math.max(0,quizIndex-1);render(true);}
 if(action==='calendar'){download('ru-exams-2-2569.ics',examICS(),'text/calendar;charset=utf-8');toast('ดาวน์โหลดปฏิทินแบบทั้งวันพร้อมรหัสคาบแล้ว');}
 if(action==='export')exportAll();
 if(action==='export-plan')exportPlan();
 if(action==='export-notes'){const text=lessons.filter(l=>state.notes[l.id]?.trim()).map(l=>`# ${l.course} — ${l.title}\n\n${state.notes[l.id]}`).join('\n\n---\n\n');download('ru-study-notes.md',text||'# ยังไม่มีบันทึก\n','text/markdown;charset=utf-8');}
 if(action==='save-transfer'){const general=Number(document.querySelector('#transfer-general').value),free=Number(document.querySelector('#transfer-free').value);if(!Number.isInteger(general)||general<0||general>30||!Number.isInteger(free)||free<0||free>12){toast('กรอกจำนวนเต็มตามช่วงที่ระบุ');return;}state.transfer={general,free};save();render(true);toast('บันทึกหน่วยกิตที่ยืนยันแล้ว');}
 if(action==='recover-session'&&confirm('ใช้ข้อมูลรอบนี้แทนข้อมูลเดิมที่อ่านไม่ได้? ควรส่งออกข้อมูลรอบนี้ก่อน')){locked=false;save();render(true);}
 reward(before,rect);
});
document.addEventListener('submit',event=>{
 if(currentView!=='debt')return;
 if(event.target.id==='debt-rate-form'){
  event.preventDefault();const values=Object.fromEntries(rateFields.map(f=>[f.key,document.querySelector('#debt-rate-'+f.key).value]));
  const error=saveRates(debtStore,values);if(error){const warning=document.querySelector('#debt-rate-error');warning.textContent=error;warning.hidden=false;return;}
  render(true);document.querySelector('#debt-interest-details')?.setAttribute?.('open','');toast('บันทึกอัตราและคำนวณประมาณการใหม่แล้ว');return;
 }
 if(event.target.id!=='debt-payment-form')return;
 event.preventDefault();
 const creditor=document.querySelector('#debt-creditor').value,amount=document.querySelector('#debt-payment-amount').value;
 const interest=document.querySelector('#debt-payment-interest')?.value||'0',fee=document.querySelector('#debt-payment-fee')?.value||'0';
 const error=debtAction('debt-add',{creditor,amount,interest,fee},debtStore);
 if(error){const warning=document.querySelector('#debt-payment-error');warning.textContent=error;warning.hidden=false;return;}
 render(true);document.querySelector('#debt-creditor').value=creditor;document.querySelector('#debt-payment-amount').focus({preventScroll:true});toast('บันทึกยอดจ่ายสะสมแล้ว');
});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='registration-search'){regQuery=el.value;document.querySelector('#registration-search-results').innerHTML=regResults();return;}if(!studySpace.info().canEdit&&el.id!=='lesson-search')return;if(el.id==='notebook-search'){notebookSearch(studySpace,el.value);return;}if(el.id==='lesson-search'){searchQuery=el.value;document.querySelector('#library-results').innerHTML=libraryResults();}if(el.id==='lesson-note'){state.notes[el.dataset.lesson]=el.value;const ok=save();document.querySelector('#note-status').textContent=ok?studySpace.info().status:'ยังไม่บันทึกใน Supabase กรุณาลองอีกครั้ง';}});
document.addEventListener('change',async event=>{const el=event.target;if(!studySpace.info().canEdit&&!['study-plan-date','calendar-course','review-course','mistakes-only','include-unread'].includes(el.id))return;
 if(el.id==='notebook-course'||el.id==='notebook-source'){notebookFilter(el.value,el.id==='notebook-source'?'source':'course');render(true);return;}
 if(el.id==='notebook-import'){try{if(el.files?.[0]){await importNotebook(el.files[0],studySpace);render();}}catch(err){toast(err.message);}return;}
 if(el.id==='study-plan-date'){if(/^\d{4}-\d{2}-\d{2}$/.test(el.value)&&el.value>=STUDY_START&&el.value<='2027-03-22'){planDate=el.value;planToolsOpen=true;render(true);}return;}
 if(el.id==='calendar-course'){calendarCourse(el.value);render(true);return;}
 if(el.id==='review-course'){reviewCourse=el.value;quizIndex=0;flipped=false;reviewQueue=null;render(true);}
 if(el.id==='mistakes-only'){mistakesOnly=el.checked;quizIndex=0;reviewQueue=null;render(true);}
 if(el.id==='include-unread'){includeUnread=el.checked;flipped=false;render(true);}
 if(el.classList.contains('grade-select')){if(el.value)state.grades[el.dataset.course]=el.value;else delete state.grades[el.dataset.course];save();render(true);toast('บันทึกผลที่กรอกแล้ว');}
 if(el.classList.contains('move-select')){state.termMoves[el.dataset.course]=Number(el.value);save();render(true);toast('ปรับภาคเรียนแล้ว ตรวจเพดานและวิชาเปิดก่อนลงจริง');}
 if(el.id==='hours-weekday'||el.id==='hours-weekend'){const v=Number(el.value);if(!studyHours.includes(v))return;state.hours[el.id==='hours-weekday'?'weekday':'weekend']=v;save();render(true);toast('ปรับเวลาอ่านส่วนตัวแล้ว แผนอ่านเปลี่ยนตาม');}
 if(el.id==='font-choice'){state.font=el.value;save();render(true);}
 if(el.id==='import-backup'){const file=el.files?.[0];if(!file)return;try{if(file.size>2*1024*1024)throw new Error('ไฟล์เกิน 2 MB');const candidate=validateState(JSON.parse(await file.text()));if(!confirm(`นำเข้าบทที่อ่านจบ ${candidate.completed.length} บท และบันทึก ${Object.keys(candidate.notes).length} รายการ เพื่อแทนที่ข้อมูลบัญชีนี้และบันทึกเข้า Supabase?`)){el.value='';return;}state=candidate;locked=false;save();render();toast('นำเข้าข้อมูลสำเร็จ');}catch(err){toast('นำเข้าไม่สำเร็จ: '+(err.message||'รูปแบบไฟล์ไม่ถูกต้อง'));el.value='';}}
});
// Remember whether the plan tools are open, so ticking a block or changing the date does not fold them away.
document.addEventListener('toggle',event=>{if(event.target?.classList?.contains('plan-tools'))planToolsOpen=event.target.open;},true);
studySpace=createStudySpace({storage,progress:state,onProgress:value=>{state=validateState(value);locked=false;},onChange:()=>render(true),onStatus:info=>{
 if(typeof document.querySelectorAll==='function')document.querySelectorAll('[data-sync-status]').forEach(el=>el.textContent=info.status);
 const bar=document.getElementById('cloud-status-bar');if(bar){bar.dataset.phase=info.phase;bar.hidden=false;}
 for(const id of ['note-status','rich-note-status']){const el=document.getElementById(id);if(el)el.textContent=info.status;}
 storageWarning(info.cacheWarning);
 const google=document.getElementById('google-signin');if(google)google.disabled=!info.providers.google;
 const setup=document.getElementById('google-setup-note');if(setup)setup.hidden=!!info.providers.google;
 const conflict=document.getElementById('sync-conflict');if(conflict)conflict.hidden=!info.conflict;
 const last=document.getElementById('last-sync');if(last)last.textContent=info.lastSync?new Date(info.lastSync).toLocaleString('th-TH'):'ยังไม่มี';
}});
